// The hypoid layout, steps 2 to 5 (docs/spiral-bevel-layout-plan.md): the pitch cones and the
// tooth trace through the mean point M, the members' blanks, the crown tooth and its mate as
// regions about the cutter's axis, the tip relief's toppings beside them, and the generating
// motions.
use std
use design
use views
use pitch.gear
use pitch.trace
use pitch.pinion
use blank.member
use crown.thickness
use crown.cutter
use crown.tooth
use crown.mate
use crown.reach
use generation

// The tip relief: a topping beside each crown. A member's tip edges are generated by its crown's
// flanks near their base, the addendum from the pitch line; a topping leaves each flank
// `tip_relief` short of that, at a kink on the flank as grown, turned `relief_angle` so the cut
// widens toward the base, and rounds into a top inside the crown. Swept with the crown it adds
// only the sliver between topping and flank: each tooth's tip edges chamfered `tip_relief` down
// its flanks. It is a sweep of its own, not a kink in the crown's region, because a concave corner
// inside one sweep trims two envelopes against each other (generating-sweep row T2); two sweeps
// meet in the kernel's Boolean instead. Its round and top keep its sheet one smooth chart.
//
// Where a topping leaves `flank`, a crown's flank as grown (a side of its region): its `kink` on
// the side's surface in the normal section `n`, at the ordinate `height` along the cutter's `ax`
// from C, beside the pitch point `near`; and the topping's flank, the cone about `ax` through the
// kink leaning `lean`.
component Topping(flank: set, ax: line, n: plane, near: point, height: Length, lean: Angle,
                  design: group) {
  // Seed: along the axis from the pitch point by the kink's height, `ax` the cutter's radius long.
  kink := point hint(at: near, along: ax, by: height / design.cutter_radius) in n
  kink coincident flank.surface
  ax.p1 distance(height, along: ax) kink
  cone := std.ConeThrough(ax, kink, lean: lean)
}

// The layout on the pitch plane `p` (`std.top`). The normal module is the trace's: a caller
// leaves `normal_module` unbound, the trace constructs it, and every depth reads it.
component HypoidLayout(p: plane, design: group, normal_module: Length) {
  gear := pitch.gear.GearCone(p, design)
  trace := pitch.trace.ToothTrace(p, gear.generator, design, normal_module: normal_module)
  pinion := pitch.pinion.PinionCone(p, gear, trace.foot, design)

  // The blanks, regions about the members' axes.
  gear_blank := blank.member.MemberBlank(gear.generator, gear.ax, design,
    normal_module: normal_module)
  pinion_blank := blank.member.MemberBlank(pinion.pitch_line, pinion.ax, design,
    normal_module: normal_module)

  // The crown, about the cutter's axis: the pinion's generator, the crown tooth, and the gear's,
  // its space cutter, on the flank cones they share.
  thickness := crown.thickness.CrownThickness(p, gear.generator, trace.normal, design)
  cutter := crown.cutter.Cutter(gear.crown_axis, trace.normal, thickness.inner_pitch,
    thickness.outer_pitch, design, normal_module: normal_module)
  tooth := crown.tooth.Tooth(cutter.inner_flank, cutter.outer_flank, cutter.tooth_base,
    cutter.tooth_tip, grow: design.backlash / 4, r: design.rounding * normal_module)
  reach := crown.reach.CutterReach(p, gear.O, trace.normal, cutter.ax, reach: design.space_reach)
  generation := generation.Generation(gear, pinion, thickness)
  construction gear_space := crown.mate.Space(cutter.outer_flank, cutter.inner_flank,
    cutter.mate_tip, cutter.mate_base, reach.cap, generation.crown_neighbor,
    grow: design.backlash / 4, r: design.rounding * normal_module)
  when design.tip_relief > 0mm {
    // The toppings, their kinks in the normal section N along the trace normal C -> M: the
    // pinion's each `tip_relief` above where its flank generates the pinion's tip edge, the
    // gear's each as far below where its flank generates the gear's, tip down; each the crown's
    // own region over the toppings' cones, from its base to a top half an addendum short of the
    // pitch plane, its flanks grown nothing (each kink is on its crown's flank as grown).
    n := views.FoldedView(p, trace.normal)
    pinion_inner := Topping(tooth.inner, cutter.ax, n.view, thickness.inner_pitch,
      height: design.tip_relief - design.addendum * normal_module,
      lean: design.pressure + design.shift + design.relief_angle, design: design)
    pinion_outer := Topping(tooth.outer, cutter.ax, n.view, thickness.outer_pitch,
      height: design.tip_relief - design.addendum * normal_module,
      lean: design.shift - design.pressure - design.relief_angle, design: design)
    pinion_top := std.Level(cutter.ax.p1, cutter.ax, d: -design.addendum * normal_module / 2)
    construction pinion_topping := crown.tooth.Tooth(pinion_inner.cone, pinion_outer.cone,
      cutter.tooth_base, pinion_top, grow: 0mm, r: design.rounding * normal_module)
    gear_outer := Topping(gear_space.inner, cutter.ax, n.view, thickness.outer_pitch,
      height: design.addendum * normal_module - design.tip_relief,
      lean: design.shift - design.pressure - design.relief_angle, design: design)
    gear_inner := Topping(gear_space.outer, cutter.ax, n.view, thickness.inner_pitch,
      height: design.addendum * normal_module - design.tip_relief,
      lean: design.pressure + design.shift + design.relief_angle, design: design)
    gear_top := std.Level(cutter.ax.p1, cutter.ax, d: design.addendum * normal_module / 2)
    construction gear_topping := crown.mate.Space(gear_outer.cone, gear_inner.cone, gear_top,
      cutter.mate_base, reach.cap, generation.crown_neighbor, grow: 0mm,
      r: design.rounding * normal_module)
  }

  // What each member is cut from and how its cutter moves.
  pinion_design := {blank: pinion_blank.material,
    generation: generation.pinion_generation, indexing: generation.pinion_index}
  gear_design := {blank: gear_blank.material,
    generation: generation.gear_generation, indexing: generation.gear_index}
}

preview {
  unit mm
  layout := HypoidLayout(std.top, design.hypoid_design)
}
